// Loads the real GGUF (path via MAGPIE_MODEL, skip 77 when unset), asserts the
// checkpoint hyperparameters and spot-checks tensor shapes -- including one
// codec tensor whose name exceeds GGML_MAX_NAME, exercising the full-name map.
#include "parity.hpp"
#include "model_loader.hpp"
#include <cstdio>
#include <exception>
#include <string>
#include <vector>

static int g_fails = 0;

#define CHECK(cond) do { \
    if (cond) { std::fprintf(stderr, "[ok]   %s\n", #cond); } \
    else      { std::fprintf(stderr, "[FAIL] %s\n", #cond); ++g_fails; } \
} while (0)

// ne is inner..outer (ggml order); trailing dims of 1 are implied.
static void check_shape(const magpie_model& m, const std::string& name,
                        std::vector<int64_t> ne) {
    ggml_tensor* t = m.tensor(name);
    if (!t) {
        std::fprintf(stderr, "[FAIL] tensor '%s' not found\n", name.c_str());
        ++g_fails;
        return;
    }
    ne.resize(GGML_MAX_DIMS, 1);
    for (int i = 0; i < GGML_MAX_DIMS; ++i) {
        if (t->ne[i] != ne[i]) {
            std::fprintf(stderr,
                "[FAIL] %s: ne[%d] = %lld, want %lld\n",
                name.c_str(), i, (long long)t->ne[i], (long long)ne[i]);
            ++g_fails;
            return;
        }
    }
    std::fprintf(stderr, "[ok]   %s shape [%lld,%lld,%lld,%lld]\n", name.c_str(),
                 (long long)t->ne[0], (long long)t->ne[1],
                 (long long)t->ne[2], (long long)t->ne[3]);
}

int main() {
    const std::string path = mgtest::env_or_skip("MAGPIE_MODEL");

    magpie_model m;
    try {
        m.load(path);
    } catch (const std::exception& e) {
        std::fprintf(stderr, "[FAIL] load: %s\n", e.what());
        return 1;
    }
    const magpie_hparams& h = m.hparams;

    // core dims
    CHECK(h.model_type == "decoder_ce");
    CHECK(h.d_model == 768);
    CHECK(h.norm_eps == 1e-5f);
    CHECK(h.activation == "gelu_tanh");
    CHECK(h.encoder.n_layers == 6);
    CHECK(h.encoder.kernel_size == 3);
    CHECK(h.encoder.is_causal);
    CHECK(h.decoder.n_layers == 12);
    CHECK(h.decoder.n_heads == 12);
    CHECK(h.decoder.d_head == 64);
    CHECK(h.decoder.d_ffn == 3072);
    CHECK(h.decoder.kernel_size == 1);
    CHECK(h.decoder.max_positions == 2048);
    CHECK(h.local_transformer.n_layers == 2);
    CHECK(h.local_transformer.max_positions == 18);
    CHECK(!h.local_transformer.apply_norm_out);
    CHECK(h.xattn.n_heads == 1);
    CHECK(h.xattn.d_head == 128);
    CHECK(h.xattn.d_memory == 768);
    CHECK(h.dec_context_size == 217);

    // vocab / special ids / frame stacking
    CHECK(h.text_vocab_size == 3359);
    CHECK(h.text_bos_id == 3357);
    CHECK(h.text_eos_id == 3358);
    CHECK(h.audio.num_codebooks == 8);
    CHECK(h.audio.codebook_size == 2016);
    CHECK(h.audio.tokens_per_codebook == 2024);
    CHECK(h.audio.bos_id == 2016);
    CHECK(h.audio.eos_id == 2017);
    CHECK(h.audio.frame_stacking_factor == 2);
    CHECK(h.audio.num_embedding_tables == 16);
    CHECK(h.audio.final_proj_dim == 32384);
    CHECK(h.speaker.count == 5);
    CHECK(h.speaker.names.size() == 5 && h.speaker.names[0] == "Aria");

    // sampling / prior defaults
    CHECK(h.sampling.temperature == 0.6f);
    CHECK(h.sampling.topk == 80);
    CHECK(h.sampling.cfg_scale == 2.5f);
    CHECK(h.sampling.max_decoder_steps == 500);
    CHECK(h.sampling.min_generated_frames == 4);
    CHECK(h.sampling.eos_detection_method == "argmax_or_multinomial_any");
    CHECK(h.prior.apply);
    CHECK(h.prior.epsilon == 0.1f);
    CHECK(h.prior.lookahead_window == 6);
    CHECK(h.prior.apply_to_layers == (std::vector<int32_t>{2,3,4,5,6,7,8,9,10}));
    CHECK(h.prior.estimate_from_layers == (std::vector<int32_t>{4,5,8,9}));

    // codec
    CHECK(h.codec.sample_rate == 22050);
    CHECK(h.codec.samples_per_frame == 1024);
    CHECK(h.codec.fsq_num_groups == 8);
    CHECK(h.codec.fsq_num_levels == (std::vector<int32_t>{8,7,6,6}));
    CHECK(h.codec.fsq_dim_base_index == (std::vector<int32_t>{1,8,56,336}));
    CHECK(h.codec.latent_dim == 32);
    CHECK(h.codec.up_sample_rates == (std::vector<int32_t>{8,8,4,2,2}));
    CHECK(h.codec.base_channels == 864);
    CHECK(h.codec.causal);

    // tokenizer summary
    CHECK(h.tokenizer.vocab_size == 3357);
    CHECK(h.tokenizer.names.size() == 15);
    CHECK(h.tokenizer.g2p_names.size() == 6);

    // tensor spot checks (ne inner..outer). The snake alpha name is 102 chars
    // (> GGML_MAX_NAME), proving the map is keyed by FULL gguf names.
    CHECK(m.tensors.size() == 535);
    check_shape(m, "text_embedding.weight", {768, 3359});
    check_shape(m, "baked_context_embedding.weight", {768, 217, 5});
    check_shape(m, "final_proj.weight", {768, 32384});
    check_shape(m, "decoder.layers.11.cross_attention.kv_net.weight", {768, 256});
    check_shape(m, "codec.audio_decoder.res_layers.0.res_blocks.0.res_blocks.0."
                   "input_activation.activation.snake_act.alpha", {1, 216, 1});
    check_shape(m, "local_transformer.position_embeddings.weight", {768, 18});

    if (g_fails) {
        std::fprintf(stderr, "test_model_load: %d check(s) FAILED\n", g_fails);
        return 1;
    }
    std::fprintf(stderr, "test_model_load: all checks passed\n");
    return 0;
}

#ifndef MAGPIE_TTS_CAPI_H
#define MAGPIE_TTS_CAPI_H

#ifdef __cplusplus
extern "C" {
#endif

// Flat C-API for magpie-tts.cpp -- designed for dlopen / cgo / purego
// (LocalAI). All functions are extern "C" and never let a C++ exception cross
// the boundary. The model is loaded ONCE into an opaque `magpie_tts_ctx` and
// reused across synthesize calls. Returned buffers are malloc'd and owned by
// the caller: release strings with magpie_tts_capi_free_string and audio with
// magpie_tts_capi_free_audio.

// Opaque synthesis context (wraps a loaded model + last-error buffer).
typedef struct magpie_tts_ctx magpie_tts_ctx;

// ABI version of this header/implementation. Bump on any breaking change to
// the function signatures or semantics below.
//
// v1: initial surface (abi_version, load, free, last_error, free_string,
//     free_audio, synthesize).
int magpie_tts_capi_abi_version(void);

// Load a GGUF model (arch "magpie-tts"). Returns an owning context, or NULL
// on failure (the reason is logged to stderr). The returned context must be
// released with magpie_tts_capi_free.
magpie_tts_ctx* magpie_tts_capi_load(const char* gguf_path);

// Free a context obtained from magpie_tts_capi_load. Safe on NULL.
void magpie_tts_capi_free(magpie_tts_ctx* ctx);

// Synthesize `text` to mono PCM f32 at 22050 Hz, samples in [-1, 1].
//   language : language code ("en", "de", "es", ...); NULL or "" = "en".
//   speaker  : baked speaker name (Aria, Jason, John, Leo, Sofia); NULL or ""
//              = the model's speaker 0 (Aria).
// On success returns a malloc'd float array (free with
// magpie_tts_capi_free_audio) and writes its length to *out_n_samples. On
// error returns NULL, writes 0 to *out_n_samples (if non-NULL) and sets the
// context's last error (see magpie_tts_capi_last_error).
float* magpie_tts_capi_synthesize(magpie_tts_ctx* ctx, const char* text,
                                  const char* language, const char* speaker,
                                  int* out_n_samples);

// Free a string previously returned by this API. Safe on NULL.
void magpie_tts_capi_free_string(char* s);

// Free an audio buffer previously returned by magpie_tts_capi_synthesize.
// Safe on NULL.
void magpie_tts_capi_free_audio(float* samples);

// Human-readable description of the last error on `ctx`, or "" if none. The
// returned pointer is owned by the context and valid until the next call on it
// (or until magpie_tts_capi_free). Returns "" if `ctx` is NULL.
const char* magpie_tts_capi_last_error(magpie_tts_ctx* ctx);

#ifdef __cplusplus
} // extern "C"
#endif

#endif // MAGPIE_TTS_CAPI_H

#pragma once
// GGUF model loader for MagpieTTS (arch "magpie-tts"): the bundled file holds
// the TTS transformer weights, the folded NanoCodec decoder, the aggregated
// tokenizer (KV) and the G2P dictionaries (byte tensors). See
// scripts/convert_magpie_to_gguf.py for the exact schema.
#include "common.hpp"
#include <cstdint>
#include <string>
#include <vector>

struct ggml_context;
struct gguf_context;
struct ggml_tensor;
struct ggml_backend;
typedef struct ggml_backend* ggml_backend_t;
struct ggml_backend_buffer;
typedef struct ggml_backend_buffer* ggml_backend_buffer_t;

// Per-stack transformer dims (text encoder / decoder / local transformer).
// All three stacks are instances of NeMo's transformer_2501.Transformer:
// pre-norm, LayerNorm without bias, fused QKV, causal-conv FFN (GELU tanh).
struct magpie_stack_hparams {
    uint32_t n_layers      = 0;
    uint32_t n_heads       = 0;   // self-attention heads
    uint32_t d_head        = 0;   // d_model / n_heads
    uint32_t d_ffn         = 0;
    uint32_t kernel_size   = 0;   // pos_ff causal-conv kernel (1 == plain linear)
    uint32_t max_positions = 0;   // learned abs pos emb rows == causal mask size
    bool     is_causal         = true;
    bool     learnable_pos_emb = true;
    bool     apply_norm_out    = true;  // final LayerNorm after the last layer
};

// Decoder cross-attention (every decoder layer attends to the text encoder).
struct magpie_xattn_hparams {
    uint32_t n_heads  = 0;   // 1 for this checkpoint
    uint32_t d_head   = 0;   // 128
    uint32_t d_memory = 0;   // 768
    bool     apply_norm_to_cond = false; // per-layer norm_xattn_memory on the memory
};

// Audio codebook layout and special token ids (shared by all 8 codebooks).
struct magpie_audio_hparams {
    uint32_t num_codebooks        = 0;  // C = 8
    uint32_t codebook_size        = 0;  // 2016 real codes
    uint32_t tokens_per_codebook  = 0;  // 2024 = 2016 + 8 specials
    uint32_t bos_id               = 0;  // 2016
    uint32_t eos_id               = 0;  // 2017
    uint32_t context_bos_id       = 0;  // 2018
    uint32_t context_eos_id       = 0;  // 2019
    uint32_t mask_token_id        = 0;  // 2020 (MaskGit only, unused)
    uint32_t frame_stacking_factor = 0; // S = 2 codec frames per decoder step
    uint32_t num_embedding_tables = 0;  // C*S = 16
    uint32_t final_proj_dim       = 0;  // C*2024*S = 32384
};

// Baked per-speaker context embeddings (replace the stripped context_encoder).
struct magpie_speaker_hparams {
    uint32_t count = 0;                  // 5
    std::vector<std::string> names;      // Aria, Jason, John, Leo, Sofia
    std::vector<int32_t>     indices;    // parallel row indices into the baked table
    uint32_t baked_t = 0;                // 217 context positions per speaker
    uint32_t baked_d = 0;                // 768
    std::vector<int32_t> baked_lengths;  // all 217
};

// Sampling defaults from the checkpoint's inference_parameters.
struct magpie_sampling_hparams {
    float    temperature        = 0.0f;  // 0.6
    uint32_t topk               = 0;     // 80
    float    cfg_scale          = 0.0f;  // 2.5
    float    argmax_temperature = 0.0f;  // 0.01 (parallel-head EOS stream)
    uint32_t max_decoder_steps  = 0;     // 500 codec frames (250 decoder steps)
    uint32_t min_generated_frames = 0;   // 4 (EOS forbidden before this)
    std::string eos_detection_method;    // "argmax_or_multinomial_any"
    bool     ignore_finished_sentence_tracking = false;
};

// Inference-time attention prior over the decoder cross-attention.
struct magpie_prior_hparams {
    bool     apply             = false;
    float    epsilon           = 0.0f;   // 0.1
    uint32_t lookahead_window  = 0;      // 6
    std::vector<int32_t> apply_to_layers;      // [2..10]
    std::vector<int32_t> estimate_from_layers; // [4,5,8,9]
    uint32_t start_after_n_audio_steps = 0;
    uint32_t sink_skip_threshold    = 0; // 8  (hardcoded in NeMo, not cfg)
    uint32_t sink_penalty_threshold = 0; // 10 (hardcoded in NeMo, not cfg)
};

// NanoCodec (FSQ dequantize + causal HiFiGAN decoder), all under magpie.codec.*.
struct magpie_codec_hparams {
    std::string name;                    // nvidia/nemo-nano-codec-22khz-...
    uint32_t sample_rate       = 0;      // 22050
    uint32_t samples_per_frame = 0;      // 1024
    uint32_t fsq_num_groups    = 0;      // 8
    std::vector<int32_t> fsq_num_levels;     // [8,7,6,6]
    std::vector<int32_t> fsq_dim_base_index; // [1,8,56,336]
    float    fsq_eps    = 0.0f;          // 1e-3 (encode side only)
    uint32_t latent_dim = 0;             // 32
    std::vector<int32_t> up_sample_rates;    // [8,8,4,2,2]
    std::vector<int32_t> up_kernel_sizes;    // [16,16,8,4,4]
    uint32_t base_channels  = 0;         // 864
    uint32_t in_kernel_size  = 0;        // 7
    uint32_t out_kernel_size = 0;        // 3
    std::vector<int32_t> resblock_kernel_sizes;   // [3,7,11]
    std::vector<int32_t> resblock_dilation_sizes; // [1,3,5]
    std::string activation;              // "half_snake"
    float    snake_eps   = 0.0f;         // 1e-9
    float    lrelu_slope = 0.0f;         // 0.01
    std::string output_activation;       // "clamp"
    std::string pad_mode;                // "zeros"
    bool     causal = false;
    bool     grouped_upsample = false;   // upsample tconvs have groups == out_channels
};

// Aggregated tokenizer summary. The per-tokenizer config blocks
// (magpie.tokenizer.<name>.*) and the full token string table
// (magpie.tokenizer.tokens) are read by magpie_tokenizer::init directly from
// magpie_model::gguf -- they are resources, not hyperparameters.
struct magpie_tokenizer_hparams {
    uint32_t vocab_size = 0;  // 3357 sub-tokenizer tokens (BOS/EOS appended by the model)
    uint32_t bos_id     = 0;  // 3357
    uint32_t eos_id     = 0;  // 3358
    std::vector<std::string> names;      // sub-tokenizers in offset order
    std::vector<int32_t>     offsets;    // global-id offset per sub-tokenizer
    std::vector<int32_t>     sizes;      // vocab size per sub-tokenizer
    std::vector<int32_t>     pad_ids;    // global pad id per sub-tokenizer (-1 if none)
    std::vector<std::string> language_map_keys;    // "en", "de", ...
    std::vector<std::string> language_map_values;  // tokenizer name per language
    std::vector<std::string> g2p_names;            // tokenizers with a g2p.<name>.dict tensor
    std::vector<std::string> g2p_heteronym_names;  // ... with a g2p.<name>.heteronyms tensor
};

// Every magpie.* KV of the GGUF (except the tokenizer resource blocks, see
// magpie_tokenizer_hparams). Nothing is defaulted from code: load() fails
// loudly listing every missing key.
struct magpie_hparams {
    std::string name;        // general.name
    std::string model_type;  // "decoder_ce"
    uint32_t d_model  = 0;   // 768 everywhere
    float    norm_eps = 0.0f;// 1e-5, LayerNorm without bias
    std::string activation;  // "gelu_tanh"

    magpie_stack_hparams encoder;            // 6L causal text encoder, FFN k=3
    magpie_stack_hparams decoder;            // 12L causal decoder, FFN k=1
    magpie_stack_hparams local_transformer;  // 2L, max pos 18, no norm_out
    magpie_xattn_hparams xattn;              // decoder cross-attention dims
    uint32_t dec_context_size = 0;           // 217 baked context positions

    // text vocabulary as seen by text_embedding (tokenizer vocab + BOS + EOS)
    uint32_t text_vocab_size = 0;  // 3359
    uint32_t text_bos_id     = 0;  // 3357 (never fed at inference)
    uint32_t text_eos_id     = 0;  // 3358 (appended to every chunk)

    magpie_audio_hparams     audio;
    magpie_speaker_hparams   speaker;
    magpie_sampling_hparams  sampling;
    magpie_prior_hparams     prior;
    magpie_codec_hparams     codec;
    magpie_tokenizer_hparams tokenizer;
};

// A loaded model: gguf metadata + host-resident weights + full-name tensor map.
struct magpie_model {
    ggml_context* ctx  = nullptr;  // owns the weight data (no_alloc=false)
    gguf_context* gguf = nullptr;  // KV + full tensor names (kept for the tokenizer)
    magpie_hparams hparams;
    // COMPUTE tensors, keyed by FULL GGUF names. 270 of the 535 names are
    // >= GGML_MAX_NAME(64) chars (max 102), so this map is built by pairing
    // gguf_get_tensor_name(i) with the i-th ggml tensor -- NEVER via
    // ggml_get_tensor / tensor->name. After upload_weights() to a device
    // backend the values are the DEVICE-resident copies (except the g2p byte
    // blobs, which never enter a graph and stay host).
    mg::tensor_map tensors;
    // HOST tensors (the gguf ctx originals), always CPU-readable via ->data.
    // Raw-float readers (embed_stack, baked speaker context, snake-alpha
    // reciprocals, tokenizer/g2p resources) must use these, never `tensors`.
    mg::tensor_map host_tensors;

    // Device weight storage (upload_weights on a non-CPU backend); nullptr on
    // the CPU path, where `tensors` aliases the host tensors.
    ggml_context*         device_ctx  = nullptr;
    ggml_backend_buffer_t weights_buf = nullptr;

    magpie_model() = default;
    magpie_model(const magpie_model&) = delete;
    magpie_model& operator=(const magpie_model&) = delete;
    ~magpie_model();

    // Loads the GGUF, reads every hparam and validates the expected tensor set
    // derived from the hparams (per-layer weights, embeddings, codec convs,
    // g2p blobs). Throws std::runtime_error listing everything that is missing.
    void load(const std::string& path);

    // Make the weights usable by graphs running on `backend`: a no-op for CPU
    // backends (graphs read the host tensors in place); for a device backend,
    // mirrors every graph-visible tensor into a backend buffer, uploads the
    // bytes, and repoints `tensors` at the device copies (host_tensors keeps
    // the host originals for raw readers). Idempotent; throws on failure.
    void upload_weights(ggml_backend_t backend);

    ggml_tensor* tensor(const std::string& full_name) const;          // nullptr if absent
    ggml_tensor* require_tensor(const std::string& full_name) const;  // throws if absent
    ggml_tensor* host_tensor(const std::string& full_name) const;
    ggml_tensor* require_host_tensor(const std::string& full_name) const;
};

#include "model_loader.hpp"
#include "ggml.h"
#include "ggml-alloc.h"
#include "ggml-backend.h"
#include "ggml-cpu.h"    // ggml_backend_is_cpu
#include "gguf.h"
#include <cstring>
#include <stdexcept>
#include <utility>
#include <vector>

// ---------------------------------------------------------------------------
// hparams
// ---------------------------------------------------------------------------

// Reads one transformer stack block. The local transformer has no
// is_causal / learnable_pos_emb KVs (they are structural facts of the NeMo
// model, both true, see docs/architecture-magpietts.md section 2.8), so those
// two reads are optional per stack.
static magpie_stack_hparams read_stack(mg::kv_reader& kv, const std::string& prefix,
                                       bool has_causal_kvs) {
    magpie_stack_hparams s;
    s.n_layers      = kv.require_u32((prefix + ".n_layers").c_str());
    s.n_heads       = kv.require_u32((prefix + ".n_heads").c_str());
    s.d_head        = kv.require_u32((prefix + ".d_head").c_str());
    s.d_ffn         = kv.require_u32((prefix + ".d_ffn").c_str());
    s.kernel_size   = kv.require_u32((prefix + ".kernel_size").c_str());
    s.max_positions = kv.require_u32((prefix + ".max_positions").c_str());
    s.apply_norm_out = kv.require_bool((prefix + ".apply_norm_out").c_str());
    if (has_causal_kvs) {
        s.is_causal         = kv.require_bool((prefix + ".is_causal").c_str());
        s.learnable_pos_emb = kv.require_bool((prefix + ".learnable_pos_emb").c_str());
    }
    return s;
}

static void read_hparams(mg::kv_reader& kv, magpie_hparams& h) {
    h.name       = kv.require_str("general.name");
    h.model_type = kv.require_str("magpie.model_type");
    h.d_model    = kv.require_u32("magpie.d_model");
    h.norm_eps   = kv.require_f32("magpie.norm_eps");
    h.activation = kv.require_str("magpie.activation");

    h.encoder           = read_stack(kv, "magpie.encoder", true);
    h.decoder           = read_stack(kv, "magpie.decoder", true);
    h.local_transformer = read_stack(kv, "magpie.local_transformer", false);

    h.xattn.n_heads  = kv.require_u32("magpie.decoder.xattn.n_heads");
    h.xattn.d_head   = kv.require_u32("magpie.decoder.xattn.d_head");
    h.xattn.d_memory = kv.require_u32("magpie.decoder.xattn.d_memory");
    h.xattn.apply_norm_to_cond = kv.require_bool("magpie.decoder.xattn.apply_norm_to_cond");
    h.dec_context_size = kv.require_u32("magpie.decoder.context_size");

    h.text_vocab_size = kv.require_u32("magpie.text.vocab_size");
    h.text_bos_id     = kv.require_u32("magpie.text.bos_id");
    h.text_eos_id     = kv.require_u32("magpie.text.eos_id");

    magpie_audio_hparams& a = h.audio;
    a.num_codebooks         = kv.require_u32("magpie.audio.num_codebooks");
    a.codebook_size         = kv.require_u32("magpie.audio.codebook_size");
    a.tokens_per_codebook   = kv.require_u32("magpie.audio.tokens_per_codebook");
    a.bos_id                = kv.require_u32("magpie.audio.bos_id");
    a.eos_id                = kv.require_u32("magpie.audio.eos_id");
    a.context_bos_id        = kv.require_u32("magpie.audio.context_bos_id");
    a.context_eos_id        = kv.require_u32("magpie.audio.context_eos_id");
    a.mask_token_id         = kv.require_u32("magpie.audio.mask_token_id");
    a.frame_stacking_factor = kv.require_u32("magpie.audio.frame_stacking_factor");
    a.num_embedding_tables  = kv.require_u32("magpie.audio.num_embedding_tables");
    a.final_proj_dim        = kv.require_u32("magpie.audio.final_proj_dim");

    magpie_speaker_hparams& sp = h.speaker;
    sp.count         = kv.require_u32("magpie.speaker.count");
    sp.names         = kv.require_arr_str("magpie.speaker.names");
    sp.indices       = kv.require_arr_i32("magpie.speaker.indices");
    sp.baked_t       = kv.require_u32("magpie.baked_context.t");
    sp.baked_d       = kv.require_u32("magpie.baked_context.d");
    sp.baked_lengths = kv.require_arr_i32("magpie.baked_context.lengths");

    magpie_sampling_hparams& s = h.sampling;
    s.temperature          = kv.require_f32("magpie.sampling.temperature");
    s.topk                 = kv.require_u32("magpie.sampling.topk");
    s.cfg_scale            = kv.require_f32("magpie.sampling.cfg_scale");
