magpie_model::~magpie_model() {
    if (weights_buf) ggml_backend_buffer_free(weights_buf);
    if (device_ctx)  ggml_free(device_ctx);
    if (gguf) gguf_free(gguf);
    if (ctx)  ggml_free(ctx);
}

void magpie_model::load(const std::string& path) {
    // no_alloc=false: every tensor's data lands in one contiguous host buffer
    // owned by ctx (CPU-first usage; a device backend uploads from it later).
    struct gguf_init_params p = { /*no_alloc=*/false, /*ctx=*/&ctx };
    gguf = gguf_init_from_file(path.c_str(), p);
    if (!gguf) throw std::runtime_error("magpie: failed to open GGUF: " + path);

    mg::kv_reader kv(gguf);
    const std::string arch = kv.require_str("general.architecture");
    read_hparams(kv, hparams);
    kv.check("magpie: hparams of '" + path + "'");
    if (arch != "magpie-tts")
        throw std::runtime_error("magpie: unexpected architecture '" + arch +
                                 "' (want magpie-tts) in " + path);

    // Build the name -> tensor map from the gguf_context: 270 of the tensor
    // names are longer than ggml_tensor::name can hold, so the FULL names are
    // paired with the ggml tensors BY INDEX (gguf creates the ctx tensors in
    // file order; with no_alloc=false the data blob tensor comes first).
    const int64_t n_tensors = gguf_get_n_tensors(gguf);
    ggml_tensor* t = ggml_get_first_tensor(ctx);
    while (t && std::strcmp(t->name, "GGUF tensor data binary blob") == 0)
        t = ggml_get_next_tensor(ctx, t);
    tensors.reserve((size_t)n_tensors);
    for (int64_t i = 0; i < n_tensors; ++i) {
        const char* full = gguf_get_tensor_name(gguf, i);
        if (!t) throw std::runtime_error(std::string("magpie: ggml context ran out of "
                    "tensors while pairing '") + full + "' (index " + std::to_string(i) + ")");
        // The truncated ggml name must be a prefix match of the full name.
        if (std::strncmp(full, t->name, GGML_MAX_NAME - 1) != 0)
            throw std::runtime_error(std::string("magpie: tensor order mismatch at index ") +
                                     std::to_string(i) + ": gguf '" + full +
                                     "' vs ggml '" + t->name + "'");
        tensors.emplace(full, t);
        t = ggml_get_next_tensor(ctx, t);
    }

    // Validate the full expected tensor set derived from the hparams.
    const std::vector<std::string> expected = expected_tensor_names(hparams);
    std::vector<std::string> missing;
    for (const std::string& name : expected)
        if (tensors.find(name) == tensors.end()) missing.push_back(name);
    if (!missing.empty()) {
        std::string msg = "magpie: '" + path + "' is missing " +
                          std::to_string(missing.size()) + " expected tensor(s):";
        for (const std::string& name : missing) msg += "\n  - " + name;
        throw std::runtime_error(msg);
    }
    if (expected.size() != tensors.size())
        MG_LOG("warning: %zu tensors in GGUF, %zu expected (extra tensors are ignored)",
               tensors.size(), expected.size());

    // Host view of every tensor, preserved across upload_weights (raw-float
    // readers and the tokenizer resources always read from here).
    host_tensors = tensors;
}

void magpie_model::upload_weights(ggml_backend_t backend) {
    if (weights_buf || !backend) return;                 // idempotent / null
    if (ggml_backend_is_cpu(backend)) return;            // host tensors work as-is

    // Mirror every graph-visible tensor into a no_alloc metadata ctx, allocate
    // that ctx in ONE backend buffer, upload the bytes from the host originals
    // and swap the compute map to the device copies. The g2p byte blobs never
    // appear in a graph, so they are skipped (their compute entry stays host).
    const size_t n = tensors.size();
    ggml_init_params dp{
        /*mem_size  =*/ ggml_tensor_overhead() * (n + 8),
        /*mem_buffer=*/ nullptr,
        /*no_alloc  =*/ true,
    };
    device_ctx = ggml_init(dp);
    if (!device_ctx) throw std::runtime_error("magpie: upload_weights ctx init failed");

    std::vector<std::pair<ggml_tensor*, const void*>> ups;
    ups.reserve(n);
    mg::tensor_map devmap;
    devmap.reserve(n);
    for (const auto& kv : tensors) {
        ggml_tensor* s = kv.second;
        if (kv.first.compare(0, 4, "g2p.") == 0) {       // host-only resource
            devmap.emplace(kv.first, s);
            continue;
        }
        ggml_tensor* d = ggml_new_tensor(device_ctx, s->type, GGML_MAX_DIMS, s->ne);
        ggml_set_name(d, s->name);   // truncated name is fine; map key is full
        devmap.emplace(kv.first, d);
        ups.emplace_back(d, s->data);
    }
    weights_buf = ggml_backend_alloc_ctx_tensors(device_ctx, backend);
    if (!weights_buf)
        throw std::runtime_error("magpie: failed to allocate device weight buffer");
    for (const auto& pr : ups)
        ggml_backend_tensor_set(pr.first, pr.second, 0, ggml_nbytes(pr.first));
    tensors.swap(devmap);
    MG_LOG("weights uploaded to %s (%.1f MiB)", ggml_backend_name(backend),
           (double)ggml_backend_buffer_get_size(weights_buf) / (1024.0 * 1024.0));
}

ggml_tensor* magpie_model::tensor(const std::string& full_name) const {
    auto it = tensors.find(full_name);
    return it == tensors.end() ? nullptr : it->second;
}

ggml_tensor* magpie_model::require_tensor(const std::string& full_name) const {
    ggml_tensor* t = tensor(full_name);
    if (!t) throw std::runtime_error("magpie: missing tensor '" + full_name + "'");
    return t;
}

ggml_tensor* magpie_model::host_tensor(const std::string& full_name) const {
    auto it = host_tensors.find(full_name);
    return it == host_tensors.end() ? nullptr : it->second;
}

ggml_tensor* magpie_model::require_host_tensor(const std::string& full_name) const {
    ggml_tensor* t = host_tensor(full_name);
    if (!t) throw std::runtime_error("magpie: missing host tensor '" + full_name + "'");
    return t;
}

// Flat C ABI over the C++ API. No exception may cross this boundary.
#include "magpie_tts_capi.h"
#include "magpie_tts.h"
#include "common.hpp"
#include <algorithm>
#include <cstdlib>
#include <exception>
#include <new>
#include <string>

struct magpie_tts_ctx {
    magpie_tts_context* inner = nullptr;
    std::string last_error;

    ~magpie_tts_ctx() { magpie_tts_free(inner); }
};

extern "C" {

int magpie_tts_capi_abi_version(void) {
    return 1;
}

magpie_tts_ctx* magpie_tts_capi_load(const char* gguf_path) {
    if (!gguf_path || !*gguf_path) {
        MG_LOG("capi_load: NULL/empty model path");
        return nullptr;
    }
    magpie_tts_ctx* ctx = new (std::nothrow) magpie_tts_ctx();
    if (!ctx) return nullptr;
    try {
        ctx->inner = magpie_tts_load(gguf_path);
        return ctx;
    } catch (const std::exception& e) {
        MG_LOG("capi_load failed: %s", e.what());
    } catch (...) {
        MG_LOG("capi_load failed: unknown exception");
    }
    delete ctx;
    return nullptr;
}

void magpie_tts_capi_free(magpie_tts_ctx* ctx) {
    delete ctx;
}

float* magpie_tts_capi_synthesize(magpie_tts_ctx* ctx, const char* text,
                                  const char* language, const char* speaker,
                                  int* out_n_samples) {
    if (out_n_samples) *out_n_samples = 0;
    if (!ctx) return nullptr;
    if (!ctx->inner) { ctx->last_error = "context has no model"; return nullptr; }
    if (!text)       { ctx->last_error = "text is NULL"; return nullptr; }
    try {
        magpie_tts_options opts;
        if (language && *language) opts.language = language;
        if (speaker  && *speaker)  opts.speaker  = speaker;
        std::vector<float> pcm = magpie_tts_synthesize(*ctx->inner, text, opts);
        float* out = (float*)std::malloc(pcm.size() * sizeof(float));
        if (!out) { ctx->last_error = "out of memory"; return nullptr; }
        std::copy(pcm.begin(), pcm.end(), out);
        if (out_n_samples) *out_n_samples = (int)pcm.size();
        return out;
    } catch (const std::exception& e) {
        ctx->last_error = e.what();
    } catch (...) {
        ctx->last_error = "unknown exception";
    }
    return nullptr;
}

void magpie_tts_capi_free_string(char* s) {
    std::free(s);
}

void magpie_tts_capi_free_audio(float* samples) {
    std::free(samples);
}

const char* magpie_tts_capi_last_error(magpie_tts_ctx* ctx) {
    return ctx ? ctx->last_error.c_str() : "";
}

} // extern "C"

// Local-transformer parity vs the NeMo reference dump.
//
// For decoder steps 0 and 5: latent = last row of the dumped decoder output,
// teacher-forced tokens = codes.final frames {2s, 2s+1} in sampled order
// (frame 0 cb 0..7 then frame 1 cb 0..7, both CFG streams see the cond
// tokens). The dump captured the projection outputs through shared memory
// AFTER NeMo's in-place edits, so the reference rows are: row 0 =
// CFG-combined (2.5*cond - 1.5*uncond), row 1 = raw uncond, both with the
// forbidden special tokens set to -inf (incl. EOS at step 0, where
// forbid_audio_eos is active). We apply the same combination host-side and
// compare the finite entries; the -inf positions are checked against the
// expected forbidden set.
#include "parity.hpp"
#include "backend.hpp"
#include "local_transformer.hpp"
#include "model_loader.hpp"
#include "ggml.h"
#include <cmath>
#include <cstring>
#include <exception>
#include <set>
#include <string>
#include <vector>

namespace {

constexpr int64_t D = 768;
constexpr float CFG_SCALE = 2.5f;

// Backend selected by MAGPIE_DEVICE (default cpu), owned by main.
mg::backend* g_be = nullptr;

std::vector<float> run_lt_step(const magpie_model& m, const std::vector<float>& latent,
                               const int32_t* toks, int32_t n_tokens) {
    mg::graph_session s(*g_be, 2048);
    ggml_tensor* lat = s.input(ggml_new_tensor_2d(s.ctx, GGML_TYPE_F32, D, 2),
                               latent.data());
    ggml_tensor* logits = magpie_lt_step_graph(s.ctx, s.graph, m, lat, toks, n_tokens);
    try {
        s.compute(4);
    } catch (const std::exception& e) {
        std::fprintf(stderr, "[lt] %s\n", e.what());
        std::exit(1);
    }
    return s.read_f32(logits);
}

// Compares got vs ref skipping ref -inf entries, and verifies the -inf set is
// exactly `forbidden` in every row.
bool compare_masked(const std::vector<float>& got, const std::vector<float>& ref,
                    int64_t n_tok, const std::set<int32_t>& forbidden,
                    const char* label, float atol) {
    if (got.size() != ref.size()) {
        std::fprintf(stderr, "[%s] size mismatch\n", label);
        return false;
    }
    // Logits reach |x| ~ 40 and the CFG combination (2.5*cond - 1.5*uncond)
    // amplifies f32 accumulation noise ~4x: observed max|d| 1.1e-4 at
    // relative error ~3e-6, so a small rtol tops up the 1e-4 atol.
    const float rtol = 1e-5f * mgtest::tol_scale();
    std::vector<float> gf, rf;
    bool mask_ok = true;
    for (size_t i = 0; i < ref.size(); ++i) {
        const int32_t tok = (int32_t)(i % n_tok);
        if (std::isinf(ref[i]) && ref[i] < 0) {
            if (!forbidden.count(tok)) {
                std::fprintf(stderr, "[%s] unexpected -inf at token %d\n", label, tok);
                mask_ok = false;
            }
        } else {
            if (forbidden.count(tok)) {
                std::fprintf(stderr, "[%s] expected -inf at token %d, got finite ref\n",
                             label, tok);
                mask_ok = false;
            }
            gf.push_back(got[i]);
            rf.push_back(ref[i]);
        }
    }
    return mgtest::compare(gf, rf, label, atol, rtol) && mask_ok;
}

} // namespace

int main() {
    const std::string model_path = mgtest::env_or_skip("MAGPIE_MODEL");
    const std::string ref_path   = mgtest::ref_dump_or_skip();

    mg::backend be;   // before the model: outlives its device weight buffer
    be.init(4);
    g_be = &be;

    magpie_model model;
    model.load(model_path);
    model.upload_weights(be.handle());
    const magpie_hparams& hp = model.hparams;
    const int64_t n_tok = hp.audio.tokens_per_codebook;  // 2024

    std::vector<int32_t> codes;
    if (!mgtest::load_baseline_i32(ref_path, "codes.final", codes)) return 1;
    const int64_t n_frames = (int64_t)codes.size() / 8;

    // forbidden specials: {bos, ctx-bos, ctx-eos, mask, reserved} always;
    // EOS additionally while forbid_audio_eos (first 2 decoder steps)
    std::set<int32_t> forbidden_base;
    for (uint32_t t = hp.audio.codebook_size; t < hp.audio.tokens_per_codebook; ++t)
        if (t != hp.audio.eos_id) forbidden_base.insert((int32_t)t);
    std::set<int32_t> forbidden_step0 = forbidden_base;
    forbidden_step0.insert((int32_t)hp.audio.eos_id);

    const float atol = 1e-4f * mgtest::tol_scale();
    bool ok = true;

    for (const int step : {0, 5}) {
        // latent = last row of the dumped decoder output, both CFG streams
        std::vector<float> dec_out;
        std::vector<int64_t> shape;
        const std::string out_name = "dec.step" + std::to_string(step) + ".out";
        if (!mgtest::load_baseline(ref_path, out_name, dec_out, shape)) return 1;
        const int64_t T = shape[1];  // [2, T, 768]
        std::vector<float> latent((size_t)2 * D);
        for (int s = 0; s < 2; ++s)
            std::memcpy(latent.data() + (size_t)s * D,
                        dec_out.data() + ((size_t)s * T + T - 1) * D, D * sizeof(float));

        // teacher-forced sampled tokens: frames 2*step, 2*step+1
        int32_t toks[16];
        for (int i = 0; i < 2; ++i)
            for (int c = 0; c < 8; ++c)
                toks[c + i * 8] = codes[(size_t)c * n_frames + 2 * step + i];

        const std::set<int32_t>& forbidden = (step == 0) ? forbidden_step0 : forbidden_base;
        for (int k = 0; k < 16; ++k) {
            std::vector<float> got = run_lt_step(model, latent, toks, k);
            // NeMo's in-place CFG on the shared-memory dump: row 0 combined
            for (int64_t j = 0; j < n_tok; ++j)
                got[j] = CFG_SCALE * got[j] + (1.0f - CFG_SCALE) * got[n_tok + j];

            std::vector<float> ref;
            const std::string name = "lt.step" + std::to_string(step) +
                                     ".cb" + std::to_string(k) + ".logits";
            if (!mgtest::load_baseline(ref_path, name, ref, shape)) return 1;
            ok &= compare_masked(got, ref, n_tok, forbidden, name.c_str(), atol);
        }
    }

    if (!ok) {
        std::fprintf(stderr, "test_lt_parity: FAILED\n");
        return 1;
    }
    std::fprintf(stderr, "test_lt_parity: all checks passed\n");
    return 0;
}

#pragma once
// Parity-test helpers for magpie-tts.cpp (adapted from parakeet's pktest).
//
// Reference dumps are GGUF files (tensors + KV) produced by
// scripts/gen_*_reference.py; the path arrives via the MAGPIE_REF_DUMP env
// var and tests SKIP (exit 77) when it is unset.
//
// IMPORTANT: baseline tensors are looked up by FULL GGUF name. Some names
// exceed GGML_MAX_NAME so ggml_tensor::name is truncated -- lookups pair
// gguf_get_tensor_name(g, i) with the i-th ggml ctx tensor BY INDEX, never
// via ggml_get_tensor.
#include "ggml.h"
#include "gguf.h"
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

namespace mgtest {

// Value of `var`, or exit 77 ("test skipped") with a message when unset/empty.
inline std::string env_or_skip(const char* var) {
    const char* v = std::getenv(var);
    if (!v || !*v) {
        std::fprintf(stderr, "[skip] %s unset, skipping test\n", var);
        std::exit(77);
    }
    return v;
}

// MAGPIE_REF_DUMP path, or exit 77 when unset.
inline std::string ref_dump_or_skip() {
    return env_or_skip("MAGPIE_REF_DUMP");
}

// Tolerance knob for non-CPU backends: MAGPIE_PARITY_TOL_SCALE multiplies a
// test's base tolerances (default 1.0 -- the CPU gates are untouched). GPU
// kernels order f32 reductions differently, so their noise floor sits a bit
// above the CPU one; the printed max|d| remains the honest parity metric.
inline float tol_scale() {
    const char* s = std::getenv("MAGPIE_PARITY_TOL_SCALE");
    if (!s || !*s) return 1.0f;
    const float v = std::strtof(s, nullptr);
    if (v > 0.0f && v != 1.0f)
        std::fprintf(stderr, "[parity] MAGPIE_PARITY_TOL_SCALE=%g\n", v);
    return v > 0.0f ? v : 1.0f;
}

// Find a tensor by FULL gguf name, pairing gguf indices with the ctx tensor
// list (skipping the no_alloc=false data-blob tensor). nullptr if absent.
inline ggml_tensor* find_tensor(const gguf_context* g, ggml_context* ctx,
                                const std::string& name) {
    const int64_t n = gguf_get_n_tensors(g);
    ggml_tensor* t = ggml_get_first_tensor(ctx);
    while (t && std::strcmp(t->name, "GGUF tensor data binary blob") == 0)
        t = ggml_get_next_tensor(ctx, t);
    for (int64_t i = 0; i < n && t; ++i, t = ggml_get_next_tensor(ctx, t))
        if (name == gguf_get_tensor_name(g, i)) return t;
    return nullptr;
}

// Load an f32 tensor (flattened, row-major) by FULL name from a baseline gguf.
inline bool load_baseline(const std::string& path, const std::string& name,
                          std::vector<float>& out, std::vector<int64_t>& shape) {
    ggml_context* ctx = nullptr;
    gguf_init_params p{ /*no_alloc=*/false, /*ctx=*/&ctx };
    gguf_context* g = gguf_init_from_file(path.c_str(), p);
    if (!g) {
        std::fprintf(stderr, "[parity] failed to open baseline: %s\n", path.c_str());
        return false;
    }
    ggml_tensor* t = find_tensor(g, ctx, name);
    if (!t) {
        std::fprintf(stderr, "[parity] tensor '%s' not found in %s\n",
                     name.c_str(), path.c_str());
        gguf_free(g);
        ggml_free(ctx);
        return false;
    }
    shape.clear();
    // Report shape outer..inner (slowest to fastest varying dimension).
    for (int i = ggml_n_dims(t) - 1; i >= 0; --i) shape.push_back(t->ne[i]);
    size_t n = (size_t)ggml_nelements(t);
    out.resize(n);
    std::memcpy(out.data(), t->data, n * sizeof(float));
    gguf_free(g);
    ggml_free(ctx);
    return true;
}

// Load an int32 tensor (flattened) by FULL name from a baseline gguf.
inline bool load_baseline_i32(const std::string& path, const std::string& name,
                              std::vector<int32_t>& out) {
    ggml_context* ctx = nullptr;
    gguf_init_params p{ /*no_alloc=*/false, /*ctx=*/&ctx };
    gguf_context* g = gguf_init_from_file(path.c_str(), p);
    if (!g) {
        std::fprintf(stderr, "[parity] failed to open baseline: %s\n", path.c_str());
        return false;
    }
    ggml_tensor* t = find_tensor(g, ctx, name);
    if (!t) {
        std::fprintf(stderr, "[parity] tensor '%s' not found in %s\n",
                     name.c_str(), path.c_str());
        gguf_free(g);
        ggml_free(ctx);
        return false;
    }
    size_t n = (size_t)ggml_nelements(t);
    out.resize(n);
    std::memcpy(out.data(), t->data, n * sizeof(int32_t));
    gguf_free(g);
    ggml_free(ctx);
    return true;
}

// Compare got vs ref; returns true if all elements are within atol + rtol*|ref|.
// Prints max/mean abs diff, the worst element, and OK/FAIL to stderr.
inline bool compare(const std::vector<float>& got, const std::vector<float>& ref,
                    const char* label, float atol, float rtol) {
    if (got.size() != ref.size()) {
        std::fprintf(stderr, "[%s] size mismatch got=%zu ref=%zu\n",
                     label, got.size(), ref.size());
        return false;
    }
    double maxabs = 0.0;
    double sumabs = 0.0;
    size_t worst = 0;
    for (size_t i = 0; i < got.size(); ++i) {
        double d = std::fabs((double)got[i] - (double)ref[i]);
        sumabs += d;
        if (d > maxabs) { maxabs = d; worst = i; }
    }
    double mean = sumabs / (got.empty() ? 1 : got.size());
    bool ok = true;
    for (size_t i = 0; i < got.size() && ok; ++i) {
        double tol = (double)atol + (double)rtol * std::fabs((double)ref[i]);
        if (std::fabs((double)got[i] - (double)ref[i]) > tol) ok = false;
    }
    std::fprintf(stderr,
        "[%s] n=%zu max|d|=%.3e mean|d|=%.3e (worst@%zu got=%.5f ref=%.5f) -> %s\n",
        label, got.size(), maxabs, mean, worst,
        got.empty() ? 0.f : got[worst], ref.empty() ? 0.f : ref[worst],
        ok ? "OK" : "FAIL");
    return ok;
}

// Read a uint32 KV entry from a baseline gguf (0 if absent / unopenable).
inline uint32_t read_u32(const std::string& path, const std::string& key) {
    gguf_init_params p{ /*no_alloc=*/true, /*ctx=*/nullptr };
    gguf_context* g = gguf_init_from_file(path.c_str(), p);
    if (!g) return 0;
    int64_t id = gguf_find_key(g, key.c_str());
    uint32_t v = (id < 0) ? 0u : gguf_get_val_u32(g, id);
    gguf_free(g);
    return v;
}

// Load a string KV entry from a baseline gguf.
inline bool load_kv_str(const std::string& path, const std::string& key,
                        std::string& out) {
    gguf_init_params p{ /*no_alloc=*/true, /*ctx=*/nullptr };
    gguf_context* g = gguf_init_from_file(path.c_str(), p);
    if (!g) {
        std::fprintf(stderr, "[parity] failed to open baseline: %s\n", path.c_str());
        return false;
    }
    int64_t id = gguf_find_key(g, key.c_str());
    if (id < 0) {
        std::fprintf(stderr, "[parity] key '%s' not found in %s\n",
                     key.c_str(), path.c_str());
        gguf_free(g);
        return false;
    }
    out = std::string(gguf_get_val_str(g, id));
    gguf_free(g);
    return true;
}

} // namespace mgtest

// Decoder parity vs the NeMo reference dump.
//
// Gates:
//   1. decoder-input reconstruction: [ctx.baked ; audio stack embeddings]
//      with CFG doubling == dec.step{0,5}.in (gates the embedding path:
//      mean over the 16 audio_embeddings tables / 16, BOS stack, layout).
//   2. full-sequence step-0 forward (empty cache, NO prior -- the reference
//      applies the prior only from step 1 on): hidden == dec.step0.out,
//      final_proj row == dec.step0.logits, post-prior cross-attn probs of
//      layers 4/5/8/9 == dec.step0.xattn.l{4,5,8,9}.
//   3. host-side prior logic: most-attended position and constructed prior
//      from the dumped step-0 scores == dec.step0.attended / dec.step0.prior;
//      prior construction for the dumped step-5 attended == dec.step5.prior.
//      (The step-5 decoder OUTPUT is not compared: the prior applied AT step 5
//      was built after step 4 and is not in the dump.)
//   4. KV-cache self-consistency: step 0 full + 1 incremental row == full
//      recompute of the 219-row input.
#include "parity.hpp"
#include "backend.hpp"
#include "decoder.hpp"
#include "prior.hpp"
#include "model_loader.hpp"
#include "ggml.h"
#include <cstring>
#include <exception>
#include <string>
#include <vector>

namespace {

constexpr int64_t D = 768;

// Backend selected by MAGPIE_DEVICE (default cpu); created in main before the
// model so it outlives the model's device weight buffer.
mg::backend* g_be = nullptr;

// Mean of the 16 audio-embedding table rows (table k = c + i*8, token order
// matching NeMo's embed_audio_tokens accumulation), divided by 16. Host read.
std::vector<float> embed_stack(const magpie_model& m, const int32_t* toks16) {
    std::vector<float> out(D, 0.0f);
    for (int k = 0; k < 16; ++k) {
        ggml_tensor* t = m.require_host_tensor("audio_embeddings." + std::to_string(k) + ".weight");
        const float* row = (const float*)t->data + (size_t)toks16[k] * D;
        for (int64_t j = 0; j < D; ++j) out[j] += row[j];
    }
    for (float& v : out) v /= 16.0f;
    return out;
}

// CFG-doubled decoder input for step (n_stacks-1): stream 0 = baked context +
// audio stack embeddings, stream 1 = zeroed context + the same audio rows.
// Stack 0 is the BOS frame pair; stack s>0 embeds codec frames 2(s-1), 2s-1.
std::vector<float> build_dec_in(const magpie_model& m, const std::vector<float>& ctx_baked,
                                const std::vector<int32_t>& codes, int64_t n_frames,
                                int n_stacks, uint32_t bos_id) {
    const int64_t T_ctx = (int64_t)ctx_baked.size() / D;
    const int64_t T = T_ctx + n_stacks;
    std::vector<float> v((size_t)2 * T * D, 0.0f);
    std::memcpy(v.data(), ctx_baked.data(), ctx_baked.size() * sizeof(float)); // stream 0 ctx
    for (int s = 0; s < n_stacks; ++s) {
        int32_t toks[16];
        for (int i = 0; i < 2; ++i) {
            for (int c = 0; c < 8; ++c) {
                const int64_t frame = 2 * (int64_t)(s - 1) + i;
                toks[c + i * 8] = (s == 0) ? (int32_t)bos_id
                                           : codes[(size_t)c * n_frames + frame];
            }
        }
        const std::vector<float> emb = embed_stack(m, toks);
        for (int stream = 0; stream < 2; ++stream)
            std::memcpy(v.data() + ((size_t)stream * T + T_ctx + s) * D,
                        emb.data(), emb.size() * sizeof(float));
    }
    return v;
}

struct dec_result {
    std::vector<float> hidden, latent, logits;
    std::vector<std::vector<float>> xattn;  // per estimate layer, flat [t_text * n_stream]
};

// Builds + computes one decoder step on g_be. memory_cond (t_text*768,
// conditional stream) is required only while the cross K/V are not yet filled.
dec_result run_dec_step(const magpie_model& m, magpie_dec_kv_cache& cache,
                        const std::vector<float>& dec_in_flat, int64_t n_new,
                        const std::vector<float>* memory_cond, int64_t t_text,
                        const std::vector<float>* prior_flat) {
    mg::graph_session s(*g_be, 8192);

    ggml_tensor* dec_in = s.input(
        ggml_new_tensor_3d(s.ctx, GGML_TYPE_F32, D, n_new, 2), dec_in_flat.data());

    std::vector<float> mem_host, mask_host;                  // outlive compute()
    ggml_tensor* memory = nullptr;
    if (!cache.cross_valid) {
        mem_host.assign((size_t)2 * t_text * D, 0.0f);       // uncond = zeros
        std::memcpy(mem_host.data(), memory_cond->data(),
                    memory_cond->size() * sizeof(float));
        memory = s.input(ggml_new_tensor_3d(s.ctx, GGML_TYPE_F32, D, t_text, 2),
                         mem_host.data());
    }
    mask_host.assign((size_t)2 * t_text, 0.0f);
    for (int64_t t = 0; t < t_text; ++t) mask_host[t] = 1.0f;  // cond: all kept
    mask_host[t_text] = 1.0f;                                  // uncond: position 0 only
    ggml_tensor* mask = s.input(ggml_new_tensor_2d(s.ctx, GGML_TYPE_F32, t_text, 2),
                                mask_host.data());
    ggml_tensor* prior = nullptr;
    if (prior_flat) {
        prior = s.input(ggml_new_tensor_2d(s.ctx, GGML_TYPE_F32, t_text, 2),
                        prior_flat->data());
    }

    magpie_dec_step_out out = magpie_decoder_step_graph(s.ctx, s.graph, m, dec_in,
                                                        memory, mask, prior, cache);
    try {
        s.compute(4);
    } catch (const std::exception& e) {
        std::fprintf(stderr, "[dec] %s\n", e.what());
        std::exit(1);
    }

    dec_result r;
    r.hidden = s.read_f32(out.hidden);
    r.latent = s.read_f32(out.latent);
    r.logits = s.read_f32(out.logits);
    for (ggml_tensor* xp : out.xattn_probs) r.xattn.push_back(s.read_f32(xp));
    return r;
}

} // namespace

int main() {
    const std::string model_path = mgtest::env_or_skip("MAGPIE_MODEL");
    const std::string ref_path   = mgtest::ref_dump_or_skip();

    mg::backend be;   // before the model: outlives its device weight buffer
    be.init(4);
    g_be = &be;

    magpie_model model;
    model.load(model_path);
    model.upload_weights(be.handle());
    const magpie_hparams& hp = model.hparams;

    std::vector<int64_t> shape;
    std::vector<float> ctx_baked, enc_out;
    if (!mgtest::load_baseline(ref_path, "ctx.baked", ctx_baked, shape)) return 1;
    if (!mgtest::load_baseline(ref_path, "enc.out", enc_out, shape)) return 1;
    const int64_t t_text = (int64_t)enc_out.size() / D;

    std::vector<int32_t> codes;
    if (!mgtest::load_baseline_i32(ref_path, "codes.final", codes)) return 1;
    const int64_t n_frames = (int64_t)codes.size() / 8;  // flat layout: [codebook][frame]
    std::fprintf(stderr, "[dec] t_text=%lld frames=%lld\n",
                 (long long)t_text, (long long)n_frames);

    // GPU runs scale the graph-output gates (MAGPIE_PARITY_TOL_SCALE); the
    // host-side gates (input reconstruction, prior logic) stay exact.
    const float scale = mgtest::tol_scale();
    const float atol = 1e-4f * scale, rtol = 0.0f;
    bool ok = true;
    std::vector<float> ref;

    // ---- gate 1: decoder input reconstruction (steps 0 and 5) ----
    const std::vector<float> in0 = build_dec_in(model, ctx_baked, codes, n_frames,
                                                1, hp.audio.bos_id);
    if (!mgtest::load_baseline(ref_path, "dec.step0.in", ref, shape)) return 1;
    ok &= mgtest::compare(in0, ref, "dec.step0.in (reconstructed)", 1e-6f, 0.0f);

    const std::vector<float> in5 = build_dec_in(model, ctx_baked, codes, n_frames,
                                                6, hp.audio.bos_id);
    if (!mgtest::load_baseline(ref_path, "dec.step5.in", ref, shape)) return 1;
    ok &= mgtest::compare(in5, ref, "dec.step5.in (reconstructed)", 1e-6f, 0.0f);

    // ---- gate 2: step-0 full-sequence forward (empty cache, no prior) ----
    std::vector<float> dump_in0;
    if (!mgtest::load_baseline(ref_path, "dec.step0.in", dump_in0, shape)) return 1;
    const int64_t T0 = shape[1];  // shape outer..inner = [2, T, 768]

    magpie_dec_kv_cache cache;
    cache.init(model, 512, 2, be.handle());
    dec_result r0 = run_dec_step(model, cache, dump_in0, T0, &enc_out, t_text, nullptr);

    if (!mgtest::load_baseline(ref_path, "dec.step0.out", ref, shape)) return 1;
    ok &= mgtest::compare(r0.hidden, ref, "dec.step0.out", atol, rtol);
    if (!mgtest::load_baseline(ref_path, "dec.step0.logits", ref, shape)) return 1;
    ok &= mgtest::compare(r0.logits, ref, "dec.step0.logits", atol, rtol);

    const std::vector<int32_t>& est = hp.prior.estimate_from_layers;
    std::vector<std::vector<float>> xattn_ref(est.size());
    for (size_t i = 0; i < est.size(); ++i) {
        const std::string name = "dec.step0.xattn.l" + std::to_string(est[i]);
        if (!mgtest::load_baseline(ref_path, name, xattn_ref[i], shape)) return 1;
        ok &= mgtest::compare(r0.xattn[i], xattn_ref[i], name.c_str(), atol, rtol);
    }

    // ---- gate 3: host-side prior logic vs the dump ----
    {
        // alignment scores = mean over heads (1) then layers of the DUMPED
        // post-prior last-row probs, conditional stream (first t_text floats)
        std::vector<const float*> layer_ptrs;
        for (const auto& xr : xattn_ref) layer_ptrs.push_back(xr.data());
        const std::vector<float> scores =
            magpie_prior_alignment_scores(layer_ptrs, (int32_t)t_text,
                                          (int32_t)hp.xattn.n_heads);

        magpie_prior_state st;
        const int32_t attended = magpie_prior_most_attended(scores.data(), (int32_t)t_text,
                                                            st, hp.prior);
        std::vector<int32_t> att_ref;
        if (!mgtest::load_baseline_i32(ref_path, "dec.step0.attended", att_ref)) return 1;
        const bool att_ok = attended == att_ref[0];
        std::fprintf(stderr, "[dec.step0.attended] got=%d ref=%d -> %s\n",
                     attended, att_ref[0], att_ok ? "OK" : "FAIL");
        ok &= att_ok;

        const std::vector<float> prior =
            magpie_prior_construct(attended, (int32_t)t_text, st, hp.prior, 2);
        if (!mgtest::load_baseline(ref_path, "dec.step0.prior", ref, shape)) return 1;
        ok &= mgtest::compare(prior, ref, "dec.step0.prior", 1e-7f, 0.0f);

        // step 5: the counters cannot reach the penalty threshold within 6
        // steps, so the construction depends only on the attended position.
        if (!mgtest::load_baseline_i32(ref_path, "dec.step5.attended", att_ref)) return 1;
        const std::vector<float> prior5 =
            magpie_prior_construct(att_ref[0], (int32_t)t_text, st, hp.prior, 2);
        if (!mgtest::load_baseline(ref_path, "dec.step5.prior", ref, shape)) return 1;
        ok &= mgtest::compare(prior5, ref, "dec.step5.prior", 1e-7f, 0.0f);
    }
    std::fprintf(stderr, "[dec] step-5 output compare intentionally skipped: the prior "
                         "applied AT step 5 (built after step 4) is not in the dump\n");

    // ---- gate 4: KV-cache self-consistency ----
    {
        // incremental: advance past step 0 (caller contract), then 1 new row
        cache.n_past += (int32_t)T0;
        int32_t toks[16];
        for (int i = 0; i < 2; ++i)
            for (int c = 0; c < 8; ++c)
                toks[c + i * 8] = codes[(size_t)c * n_frames + i];  // frames 0,1
        const std::vector<float> emb = embed_stack(model, toks);
        std::vector<float> inc_in((size_t)2 * D);
        std::memcpy(inc_in.data(), emb.data(), emb.size() * sizeof(float));
        std::memcpy(inc_in.data() + D, emb.data(), emb.size() * sizeof(float));
        dec_result r_inc = run_dec_step(model, cache, inc_in, 1, nullptr, t_text, nullptr);

        // full recompute of the 219-row input with a fresh cache
        std::vector<float> full_in((size_t)2 * (T0 + 1) * D);
        for (int stream = 0; stream < 2; ++stream) {
            std::memcpy(full_in.data() + (size_t)stream * (T0 + 1) * D,
                        dump_in0.data() + (size_t)stream * T0 * D,
                        (size_t)T0 * D * sizeof(float));
            std::memcpy(full_in.data() + ((size_t)stream * (T0 + 1) + T0) * D,
                        emb.data(), emb.size() * sizeof(float));
        }
        magpie_dec_kv_cache cache2;
        cache2.init(model, 512, 2, be.handle());
        dec_result r_full = run_dec_step(model, cache2, full_in, T0 + 1,
                                         &enc_out, t_text, nullptr);

        ok &= mgtest::compare(r_inc.latent, r_full.latent,
                              "kv-cache latent (incremental vs full)", atol, 0.0f);
        ok &= mgtest::compare(r_inc.logits, r_full.logits,
                              "kv-cache logits (incremental vs full)", atol, 0.0f);
    }

    if (!ok) {
        std::fprintf(stderr, "test_decoder_parity: FAILED\n");
        return 1;
    }
    std::fprintf(stderr, "test_decoder_parity: all checks passed\n");
    return 0;
}

// Parity test for the NanoCodec decode path against the NeMo reference dump:
//   gate 1: codec_fsq_dequantize(codes.final) vs dump tensor "codec.latent"
//           (exact table lookup -> atol 1e-7)
//   gate 2: codec_decode(codes.final) vs dump tensor "wav"
//           (f32 conv chains -> atol 1e-4)
// Needs MAGPIE_MODEL and MAGPIE_REF_DUMP; skips (77) when either is unset.
#include "parity.hpp"
#include "backend.hpp"
#include "codec.hpp"
#include "model_loader.hpp"

#include <chrono>
#include <cstdio>
#include <exception>

int main() {
    const std::string model_path = mgtest::env_or_skip("MAGPIE_MODEL");
    const std::string ref        = mgtest::ref_dump_or_skip();

    mg::backend be;   // before the model: outlives its device weight buffer
    be.init();

    magpie_model model;
    try {
        model.load(model_path);
        model.upload_weights(be.handle());
    } catch (const std::exception& e) {
        std::fprintf(stderr, "[codec] model load failed: %s\n", e.what());
        return 1;
    }

    // codes.final: codebook-major int32 [C=8, T], ids in [0, 2016)
    std::vector<int32_t> codes;
    if (!mgtest::load_baseline_i32(ref, "codes.final", codes)) return 1;
    const int32_t n_codebooks = (int32_t)model.hparams.codec.fsq_num_groups;
    if (n_codebooks <= 0 || codes.empty() || codes.size() % n_codebooks != 0) {
        std::fprintf(stderr, "[codec] bad codes.final size %zu for %d codebooks\n",
                     codes.size(), n_codebooks);
        return 1;
    }
    const int32_t n_frames = (int32_t)(codes.size() / n_codebooks);
    std::fprintf(stderr, "[codec] %d codebooks x %d frames\n", n_codebooks, n_frames);

    bool ok = true;
    try {
        // ---- gate 1: FSQ dequantize, exact ---------------------------------
        std::vector<float>   ref_latent;
        std::vector<int64_t> latent_shape;
        if (!mgtest::load_baseline(ref, "codec.latent", ref_latent, latent_shape)) return 1;
        const std::vector<float> latent =
            codec_fsq_dequantize(model, codes.data(), n_frames);
        ok &= mgtest::compare(latent, ref_latent, "codec.fsq_latent", 1e-7f, 0.0f);

        // ---- gate 2: full decode ------------------------------------------
        std::vector<float>   ref_wav;
        std::vector<int64_t> wav_shape;
        if (!mgtest::load_baseline(ref, "wav", ref_wav, wav_shape)) return 1;

        const auto t0 = std::chrono::steady_clock::now();
        const std::vector<float> wav = codec_decode(model, codes.data(), n_frames, &be);
        const auto t1 = std::chrono::steady_clock::now();
        const double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
        std::fprintf(stderr, "[codec] decoded %d frames -> %zu samples in %.1f ms "
                     "(%.2fx realtime at %u Hz)\n",
                     n_frames, wav.size(), ms,
                     (double)wav.size() / (double)model.hparams.codec.sample_rate /
                         (ms / 1000.0),
                     model.hparams.codec.sample_rate);

        const size_t want = (size_t)model.hparams.codec.samples_per_frame * n_frames;
        if (wav.size() != want) {
            std::fprintf(stderr, "[codec] wav length %zu != expected %zu\n",
                         wav.size(), want);
            ok = false;
        }
        ok &= mgtest::compare(wav, ref_wav, "codec.wav",
                              1e-4f * mgtest::tol_scale(), 0.0f);
    } catch (const std::exception& e) {
        std::fprintf(stderr, "[codec] exception: %s\n", e.what());
        return 1;
    }
    return ok ? 0 : 1;
}

// Encoder parity vs the NeMo reference dump:
//   1. text_embedding rows of tok.ids  == enc.in
//   2. per-layer encoder outputs       == enc.layer{0..5}.out
//   3. final (post norm_out) output    == enc.out
// Runs on the backend selected by MAGPIE_DEVICE (default cpu); GPU runs relax
// the gates via MAGPIE_PARITY_TOL_SCALE (see parity.hpp).
#include "parity.hpp"
#include "backend.hpp"
#include "encoder.hpp"
#include "model_loader.hpp"
#include "ggml.h"
#include <string>
#include <vector>

int main() {
    const std::string model_path = mgtest::env_or_skip("MAGPIE_MODEL");
    const std::string ref_path   = mgtest::ref_dump_or_skip();

    mg::backend be;   // declared before the model: outlives its device buffer
    be.init(4);

    magpie_model model;
    model.load(model_path);
    model.upload_weights(be.handle());

    std::vector<int32_t> tok_ids;
    if (!mgtest::load_baseline_i32(ref_path, "tok.ids", tok_ids)) return 1;
    const int64_t T = (int64_t)tok_ids.size();
    std::fprintf(stderr, "[enc] %lld text tokens (device %s)\n",
                 (long long)T, be.device_name());

    mg::graph_session s(be, 4096);
    ggml_tensor* tokens = s.input(
        ggml_new_tensor_1d(s.ctx, GGML_TYPE_I32, T), tok_ids.data());

    // gate 1: raw token embeddings (the encoder adds pos emb on top of these)
    ggml_tensor* emb = ggml_get_rows(s.ctx, model.require_tensor("text_embedding.weight"),
                                     tokens);
    s.mark_output(emb);
    ggml_build_forward_expand(s.graph, emb);

    std::vector<ggml_tensor*> layer_outs;
    ggml_tensor* enc_out = magpie_encoder_graph(s.ctx, s.graph, model, tokens,
                                                &layer_outs);
    s.compute(4);

    // Pre-norm residual activations grow to |x| ~ 950 by layer 5; the f32
    // accumulation-order noise vs PyTorch is ~3e-7 RELATIVE (max|d| 2.4e-4 on
    // those huge values), so the raw layer outputs get a small rtol on top of
    // the 1e-4 atol. The post-LayerNorm enc.out passes atol 1e-4 alone.
    const float scale = mgtest::tol_scale();
    const float atol = 1e-4f * scale, rtol = 1e-5f * scale;
    bool ok = true;
    std::vector<float> ref;
    std::vector<int64_t> shape;

    if (!mgtest::load_baseline(ref_path, "enc.in", ref, shape)) return 1;
    ok &= mgtest::compare(s.read_f32(emb), ref, "enc.in", atol, rtol);

    for (size_t l = 0; l < layer_outs.size(); ++l) {
        const std::string name = "enc.layer" + std::to_string(l) + ".out";
        if (!mgtest::load_baseline(ref_path, name, ref, shape)) return 1;
        ok &= mgtest::compare(s.read_f32(layer_outs[l]), ref, name.c_str(), atol, rtol);
    }

    if (!mgtest::load_baseline(ref_path, "enc.out", ref, shape)) return 1;
    ok &= mgtest::compare(s.read_f32(enc_out), ref, "enc.out", atol, rtol);

    if (!ok) {
        std::fprintf(stderr, "test_encoder_parity: FAILED\n");
        return 1;
    }
    std::fprintf(stderr, "test_encoder_parity: all checks passed\n");
    return 0;
}

// Tokenizer parity: exact integer-equality checks of magpie_tokenizer::encode
// against (a) golden encodings captured from the NeMo tokenizers (embedded
// below, no dump needed) and (b) the reference dump's tok.ids (text/language
// from the dump's ref.* KV, EOS appended like NeMo's chunk_text_for_inference).
//
// The golden vectors were produced by running the actual NeMo classes
// (IPATokenizer/IpaG2p with phoneme_probability=1.0, ArabicCharsTokenizer
// charset v1, HF google/byt5-small) on the extracted checkpoint resources and
// adding each sub-tokenizer's global offset. Note the ByT5 streams end in
// offset+1: HF encode(add_special_tokens=True) appends </s> (local id 1).
//
// Skips 77 when MAGPIE_MODEL is unset, and (after the self-contained golden
// checks pass) when MAGPIE_REF_DUMP is unset.
#include "parity.hpp"
#include "model_loader.hpp"
#include "tokenizer.hpp"

#include <cstdio>
#include <exception>
#include <string>
#include <vector>

static int g_fails = 0;

static std::string ids_str(const std::vector<int32_t>& v) {
    std::string s = "[";
    for (size_t i = 0; i < v.size(); ++i) {
        if (i) s += ",";
        s += std::to_string(v[i]);
    }
    return s + "]";
}

static void check_ids(const magpie_tokenizer& tok, const char* lang, const char* text,
                      const std::vector<int32_t>& want) {
    std::vector<int32_t> got;
    try {
        got = tok.encode(text, lang);
    } catch (const std::exception& e) {
        std::fprintf(stderr, "[FAIL] %s \"%s\": encode threw: %s\n", lang, text, e.what());
        ++g_fails;
        return;
    }
    if (got == want) {
        std::fprintf(stderr, "[ok]   %s \"%s\" (%zu ids)\n", lang, text, got.size());
    } else {
        std::fprintf(stderr, "[FAIL] %s \"%s\"\n  got  %s\n  want %s\n",
                     lang, text, ids_str(got).c_str(), ids_str(want).c_str());
        ++g_fails;
    }
}

static void check_throws(const magpie_tokenizer& tok, const char* lang, const char* text) {
    try {
        tok.encode(text, lang);
        std::fprintf(stderr, "[FAIL] %s: expected encode to throw\n", lang);
        ++g_fails;
    } catch (const std::exception& e) {
        std::fprintf(stderr, "[ok]   %s throws: %s\n", lang, e.what());
    }
}

int main() {
    const std::string model_path = mgtest::env_or_skip("MAGPIE_MODEL");

    magpie_model model;
