        {90,68,81,59,90,61,62,87,61,93,45,46,47,47,46,38,6,90,54,66,93,23,33,22,
         39,28,29,33,26});
    // digits ride inside the punctuation chunk, uppercase OOV -> graphemes
    check_ids(tok, "en", "NVIDIA GPU 123 test",
