        {90,50,84,93,39,26,22,25,93,90,88,93,90,51,87,58,20,93,75,79,93,23,22,40,
         40,93,90,68,77,69,93,33,30,43,26,7});
    // synoglyphs (curly quotes) + NFD-strip (cafe / naive)
