    // es (spanish_phoneme, offset 480, pad_with_space=true): dict word
    // "hola" -> HOLA -> [ˈ,o,l,a], wrapped in spaces
    check_ids(tok, "es", "hola", {580,571,532,529,520,580});
    check_ids(tok, "es", "Hola mundo.",
